package com.luc4n3x.levyra.ui.i18n

import com.luc4n3x.levyra.domain.LevyraLanguageCatalog

internal class DiscoveryCopy(private val values: List<String>) {
    fun brazilian(): DiscoveryCopy = DiscoveryCopy(values.map(LevyraBrazilianPortuguese::adapt))

    init { require(values.size == DISCOVERY_COPY_SIZE && values.all(String::isNotBlank)) }
    val title get() = values[0]
    val lead get() = values[1]
    val start get() = values[2]
    val save get() = values[3]
    val skip get() = values[4]
    val undo get() = values[5]
    val playPreview get() = values[6]
    val pausePreview get() = values[7]
    val playFull get() = values[8]
    val weeklyPlaylist get() = values[9]
    val savedMessage get() = values[10]
    val savedThisWeek get() = values[11]
    val reasonNewRelease get() = values[12]
    val reasonFollowedArtist get() = values[13]
    fun reasonBecause(track: String): String = values[14].replace("{track}", track)
    val reasonSimilarArtist get() = values[15]
    val reasonTrending get() = values[16]
    val reasonEditorial get() = values[17]
    val loading get() = values[18]
    val error get() = values[19]
    val retry get() = values[20]
    val empty get() = values[21]
    val previewUnavailable get() = values[22]
    val swipeHint get() = values[23]
    val openSaved get() = values[24]
    fun cardDescription(title: String, artist: String): String = values[25].replace("{title}", title).replace("{artist}", artist)
    val saveFailed get() = values[26]
    val close get() = values[27]
    val refresh get() = values[28]
    val previewLoading get() = values[29]
}

internal const val DISCOVERY_COPY_SIZE = 30

internal fun discoveryCopy(code: String): DiscoveryCopy =
    if (isBrazilianPortuguese(code)) brazilianDiscoveryCopy else discoveryCopies.getValue(translationKey(code))

private val brazilianDiscoveryCopy: DiscoveryCopy by lazy(LazyThreadSafetyMode.PUBLICATION) {
    discoveryCopies.getValue("pt").brazilian()
}

internal fun discoveryCopyLanguages(): Set<String> = discoveryCopies.keys

